    elif 'fever' in patient.symptoms or 'tiredness' in patient.symptoms:
        score += 1

    # Increase priority based on age
    if patient.age > 50:
        score += 2
    elif patient.age > 30:
        score += 1

    # Decrease priority based on resource availability
    if patient.resource_availability == 'limited':
        score -= 2
    elif patient.resource_availability == 'moderate':
        score -= 1

    return score

