def canFormPalindrome(string):
    count = [0]*256 
    for i in range(0, len(string)): 
        count[ord(string[i])] = count[ord(string[i])] + 1

    odd = 0
    for i in range(0, 256): 
        if (count[i] & 1): 
            odd = odd + 1

    if (odd > 1): 
        return False
    else: 
        return True

