def factorial(n):
    # Check if n is less than 0
    if n < 0:
        return "Factorial is not defined for negative numbers"
    # Check if n is 0 or 1
    elif n == 0 or n == 1:
        return 1
    else:
        result = 1
        # Multiply result by all integers from 2 to n
        for i in range(2, n + 1):
            result *= i
        return result

