def average_except_min_max(lst):
    # checking if list has at least three elements
    if len(lst) < 3: 
        return "List should contain at least three numbers"
    min_num = min(lst)
    max_num = max(lst)
    sum_num = sum(lst) - min_num - max_num
    return sum_num / (len(lst) - 2)

